
import json
from datetime import datetime, timezone
from pathlib import Path
from uuid import uuid4


PROJECT_ROOT = Path(__file__).resolve().parents[3]

ALERT_PATH = (
    PROJECT_ROOT
    / "data"
    / "artifacts"
    / "monitoring"
    / "unified_alert.json"
)

OUTPUT_PATH = (
    PROJECT_ROOT
    / "data"
    / "artifacts"
    / "diagnosis"
    / "diagnosis_result.json"
)


def load_unified_alert():
    """Load the unified alert generated by ML Monitoring."""
    if not ALERT_PATH.exists():
        raise FileNotFoundError(
            f"Unified alert not found: {ALERT_PATH}"
        )

    with ALERT_PATH.open("r", encoding="utf-8") as file:
        return json.load(file)


def find_alert(alert, alert_type):
    """Find a monitoring result by type."""
    for condition in alert.get("alerts", []):
        if condition.get("type") == alert_type:
            return condition
    return None


def diagnose_data_drift(alert):
    condition = find_alert(alert, "data_drift")

    if not condition or condition.get("status") != "detected":
        return None

    return {
        "issue": "data_distribution_change",
        "status": "detected",
        "evidence": {
            "drifted_feature_count": condition.get(
                "drifted_feature_count"
            ),
            "total_feature_count": condition.get(
                "total_feature_count"
            ),
            "drift_rate": condition.get("drift_rate"),
            "drifted_features": condition.get(
                "drifted_features", []
            ),
        },
        "investigation_area": "input_data",
    }


def diagnose_prediction_drift(alert):
    condition = find_alert(alert, "prediction_drift")

    if not condition or condition.get("status") != "detected":
        return None

    return {
        "issue": "prediction_distribution_change",
        "status": "detected",
        "evidence": {
            "ks_statistic": condition.get("ks_statistic"),
            "p_value": condition.get("p_value"),
            "positive_prediction_rate_difference": condition.get(
                "positive_prediction_rate_difference"
            ),
        },
        "investigation_area": "model_predictions",
    }


def diagnose_performance_degradation(alert):
    condition = find_alert(alert, "performance_degradation")

    if not condition or condition.get("status") != "detected":
        return None

    return {
        "issue": "model_performance_degradation",
        "status": "detected",
        "evidence": {
            "degraded_metric_count": condition.get(
                "degraded_metric_count"
            ),
            "total_metrics_evaluated": condition.get(
                "total_metrics_evaluated"
            ),
            "degraded_metrics": condition.get(
                "degraded_metrics", []
            ),
        },
        "investigation_area": "model_performance",
    }


def diagnose_data_quality(alert):
    condition = find_alert(alert, "data_quality")

    if not condition or condition.get("status") not in {
        "failed",
        "warning",
    }:
        return None

    failed_checks = condition.get("failed_checks", [])
    warning_checks = condition.get("warning_checks", [])

    # A warning is recorded for investigation but is not represented
    # as a confirmed data-quality failure.
    if condition.get("status") == "failed":
        issue_status = "failed"
    else:
        issue_status = "warning"

    check_details = condition.get("checks", {})

    return {
        "issue": "telemetry_data_quality_issue",
        "status": issue_status,
        "evidence": {
            "failed_checks": failed_checks,
            "warning_checks": warning_checks,
            "check_details": {
                name: check_details[name]
                for name in failed_checks + warning_checks
                if name in check_details
            },
        },
        "investigation_area": "prediction_telemetry",
    }


def generate_diagnosis(alert):
    """Generate structured diagnoses from a unified monitoring alert."""
    diagnoses = []

    diagnosis_functions = [
        diagnose_data_drift,
        diagnose_prediction_drift,
        diagnose_performance_degradation,
        diagnose_data_quality,
    ]

    for diagnosis_function in diagnosis_functions:
        result = diagnosis_function(alert)
        if result:
            diagnoses.append(result)

    # Only detected failures/issues count as confirmed issues.
    confirmed_issues = [
        item for item in diagnoses
        if item["status"] in {"detected", "failed"}
    ]

    overall_status = (
        "issues_detected"
        if confirmed_issues
        else "no_issue_detected"
    )

    return {
        "diagnosis_id": f"diagnosis-{uuid4().hex}",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "model": alert.get("model", {}),
        "source_alert_id": alert.get("alert_id"),
        "overall_status": overall_status,
        "alert_severity": alert.get("severity"),
        "diagnoses": diagnoses,
    }


def save_diagnosis(diagnosis):
    """Save the diagnosis result as JSON."""
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)

    with OUTPUT_PATH.open("w", encoding="utf-8") as file:
        json.dump(diagnosis, file, indent=4)

    print(f"Diagnosis saved to: {OUTPUT_PATH}")


def main():
    print("=" * 60)
    print("INTELLICORE AI - DIAGNOSIS ENGINE")
    print("=" * 60)

    alert = load_unified_alert()
    diagnosis = generate_diagnosis(alert)

    print(f"Alert ID: {alert.get('alert_id')}")
    print(f"Model: {alert.get('model', {}).get('model_name')}")
    print(f"Severity: {alert.get('severity')}")
    print(f"Overall Status: {diagnosis['overall_status']}")
    print(f"Diagnoses Generated: {len(diagnosis['diagnoses'])}")

    for item in diagnosis["diagnoses"]:
        print(f"- {item['issue']}: {item['status']}")

    save_diagnosis(diagnosis)


if __name__ == "__main__":
    main()
